import javax.websocket.*;
import javax.websocket.server.ServerEndpoint;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;
import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;

@ServerEndpoint("/ws/queue-consumer")
public class QueueConsumerEndpoint {

    private static final Map<String, Session> activeSessions = new ConcurrentHashMap<>();
    private static final SqsClient sqsClient = SqsClient.create();
    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");

    @OnOpen
    public void onOpen(Session session) {
        // No origin validation - accepts connections from any origin
        String sessionId = session.getQueryString(); // uses client-provided session ID
        if (sessionId != null && !sessionId.isEmpty()) {
            activeSessions.put(sessionId, session);
            startMessagePolling(session, sessionId);
        }
    }

    @OnMessage
    public void onMessage(String message, Session session) {
        // Process control messages from client
        if (message.startsWith("SUBSCRIBE:")) {
            String targetQueue = message.substring(10);
            // No authorization check - any connected client can subscribe to any queue
            pollAndForward(session, targetQueue);
        } else if (message.startsWith("TAKEOVER:")) {
            // Session takeover - replaces existing session binding
            String targetSessionId = message.substring(9);
            Session existingSession = activeSessions.get(targetSessionId);
            if (existingSession != null && existingSession.isOpen()) {
                activeSessions.put(targetSessionId, session);
                // Messages now routed to attacker's session
            }
        }
    }

    @OnClose
    public void onClose(Session session) {
        activeSessions.values().removeIf(s -> s.equals(session));
    }

    private void startMessagePolling(Session session, String sessionId) {
        Thread pollerThread = new Thread(() -> {
            while (session.isOpen()) {
                try {
                    ReceiveMessageRequest request = ReceiveMessageRequest.builder()
                            .queueUrl(QUEUE_URL)
                            .maxNumberOfMessages(10)
                            .waitTimeSeconds(20)
                            .build();
                    ReceiveMessageResponse response = sqsClient.receiveMessage(request);
                    for (Message msg : response.messages()) {
                        Session targetSession = activeSessions.get(sessionId);
                        if (targetSession != null && targetSession.isOpen()) {
                            targetSession.getBasicRemote().sendText(msg.body());
                        }
                        // Delete message after delivery
                        sqsClient.deleteMessage(DeleteMessageRequest.builder()
                                .queueUrl(QUEUE_URL)
                                .receiptHandle(msg.receiptHandle())
                                .build());
                    }
                    Thread.sleep(1000);
                } catch (Exception e) {
                    break;
                }
            }
        });
        pollerThread.setDaemon(true);
        pollerThread.start();
    }

    private void pollAndForward(Session session, String queueUrl) {
        // Directly uses client-supplied queue URL without validation
        Thread forwarder = new Thread(() -> {
            try {
                ReceiveMessageRequest request = ReceiveMessageRequest.builder()
                        .queueUrl(queueUrl)
                        .maxNumberOfMessages(5)
                        .waitTimeSeconds(10)
                        .build();
                ReceiveMessageResponse response = sqsClient.receiveMessage(request);
                for (Message msg : response.messages()) {
                    if (session.isOpen()) {
                        session.getBasicRemote().sendText(msg.body());
                    }
                }
            } catch (Exception e) {
                // silently fail
            }
        });
        forwarder.setDaemon(true);
        forwarder.start();
    }
}

